<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import * as api from '../../api/admin'
import type { Schema } from '../../types/api'
import AppDrawer from '../../components/AppDrawer.vue'
import AppDialog from '../../components/AppDialog.vue'
import { useAdminRequest } from './shared'
const {busy,error,run}=useAdminRequest()
const prices=ref<Schema<'PriceVersion'>[]>([]), specs=ref<Schema<'SpecVersion'>[]>([]), open=ref(false), confirm=ref(false), notice=ref('')
const draft=ref<Schema<'PriceDraft'>>(blank())
const latest=computed(()=>prices.value.find(x=>x.spec_id===draft.value.spec_id))
function blank():Schema<'PriceDraft'> {return {spec_id:'',version:'',expected_version:null,enabled:false,credits:0,policy_version:'',reason:''}}
function load(){return run(()=>Promise.all([api.listPrices(),api.listSpecs()]),([p,s])=>{prices.value=p;specs.value=s})}
function edit(row?:Schema<'PriceVersion'>){draft.value=row?{...row,expected_version:row.version,version:'',reason:''}:blank();error.value='';open.value=true}
async function save(){if(await run(()=>api.savePrice({...draft.value}),()=>{open.value=false;confirm.value=false;notice.value='价格版本已发布，用户提交前将重新校验报价。'})) await load()}
onMounted(load)
</script>
<template><div class="admin-page"><header class="page-heading"><h1>规格价格</h1><p>按规格维护积分价格，发布前明确确认。</p></header><p v-if="error" class="field-error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><section class="panel"><div class="section-heading"><h2>当前价格</h2><div class="action-row"><button class="button" :disabled="busy" @click="load">刷新价格</button><button class="button primary" :disabled="busy" @click="edit()">新增价格</button></div></div><div class="admin-table"><table><thead><tr><th>规格</th><th>积分</th><th>版本</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in prices" :key="p.spec_id"><td>{{ specs.find(s=>s.spec_id===p.spec_id)?.name || p.spec_id }}</td><td>{{ p.credits }}</td><td>{{ p.version }}</td><td>{{ p.enabled?'启用':'停用' }}</td><td><button class="button" :disabled="busy" @click="edit(p)">编辑价格</button></td></tr></tbody></table></div><p v-if="!busy && !prices.length">暂无价格。</p></section></div>
<AppDrawer v-model:open="open" title="编辑价格版本" purpose="edit"><form id="price-form" class="form-stack" @submit.prevent="confirm=true"><p>基于版本：{{ draft.expected_version || '新建' }}</p><label>规格<select v-model="draft.spec_id" data-initial-focus required :disabled="!!draft.expected_version"><option value="">选择规格</option><option v-for="s in specs" :key="s.spec_id" :value="s.spec_id">{{ s.name }}</option></select></label><label>新版本号<input v-model="draft.version" required pattern="[\w.-]+"></label><label>每次生成积分<input v-model.number="draft.credits" type="number" min="0" step="1" required></label><label>D-05 价格政策版本<input v-model="draft.policy_version" required></label><label>发布后状态<select v-model="draft.enabled"><option :value="false">停用</option><option :value="true">启用</option></select></label><label>调价原因<textarea v-model="draft.reason" required maxlength="500" /></label><p v-if="error" class="field-error" role="alert">{{ error }}</p><button type="button" class="button" :disabled="busy" @click="load">核对最新价格（保留草稿）</button><template v-if="latest"><p>当前：{{ latest.credits }} 积分 · {{ latest.version }}</p><button v-if="latest.version!==draft.expected_version" type="button" class="button" @click="draft.expected_version=latest.version">已核对，采用当前版本</button></template></form><template #actions><button class="button primary" form="price-form" :disabled="busy">确认价格信息</button></template></AppDrawer>
<AppDialog v-model:open="confirm" title="确认发布价格" purpose="charge"><p>规格 {{ specs.find(s=>s.spec_id===draft.spec_id)?.name }} 将发布 {{ draft.credits }} 积分价格，状态为{{ draft.enabled?'启用':'停用' }}。</p><p>新价格不改变已受理任务的收费快照。</p><p>{{ draft.reason }}</p><p v-if="error" role="alert" class="field-error">{{ error }}</p><template #actions><button class="button danger" :disabled="busy" @click="save">发布价格</button></template></AppDialog></template>
